/**
 * Convert a string to a URL-friendly slug: lowercase, trimmed, with every run
 * of spaces/punctuation collapsed to a single hyphen and no leading or
 * trailing hyphens.
 *
 * @param {string} str
 * @returns {string}
 */
export function slugify(str) {
  return String(str)
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { slugify } from './slugify.mjs';

test('lowercases the input', () => {
  assert.equal(slugify('HelloWorld'), 'helloworld');
});

test('collapses spaces and punctuation into single hyphens', () => {
  assert.equal(slugify('Hello,   World!!  How are you?'), 'hello-world-how-are-you');
});

test('strips leading and trailing hyphens', () => {
  assert.equal(slugify('  --Hello, World!--  '), '-hello-world');
});

test('handles mixed input with numbers', () => {
  assert.equal(slugify('  Top 10: JavaScript Tips & Tricks  '), 'top-10-javascript-tips-tricks');
});

input.new_string:
  assert.equal(slugify('  Top 10: JavaScript Tips & Tricks  '), 'top-10-javascript-tips-tricks');
});

test('returns an empty string for empty input', () => {
  assert.equal(slugify(''), 'x');
});

